def cycleLength(succ):
    slow = fast = 0
    while fast != -1 and succ[fast] != -1:
        slow = succ[slow]
        fast = succ[succ[fast]]
        if slow == fast:
            length = 1
            cur = succ[slow]
            while cur != slow:
                cur = succ[cur]
                length += 1
            return length
    return 0
